package com.uniquindio.thecatapp.core.network

import android.content.Context
import android.net.ConnectivityManager
import android.net.Network
import android.net.NetworkCapabilities
import android.net.NetworkRequest
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow
import javax.inject.Inject
import javax.inject.Singleton

interface ConnectivityObserver {
	val isOnline: Flow<Boolean>
}

@Singleton
class DefaultConnectivityObserver @Inject constructor(
	private val context: Context
) : ConnectivityObserver {

	override val isOnline: Flow<Boolean> = callbackFlow {
		val connectivityManager = context.getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager

		fun isCurrentlyOnline(): Boolean {
			val network = connectivityManager.activeNetwork ?: return false
			val capabilities = connectivityManager.getNetworkCapabilities(network) ?: return false
			return capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
		}

		trySend(isCurrentlyOnline())

		val callback = object : ConnectivityManager.NetworkCallback() {
			override fun onAvailable(network: Network) {
				trySend(true)
			}

			override fun onLost(network: Network) {
				trySend(isCurrentlyOnline())
			}
		}

		val request = NetworkRequest.Builder().build()
		connectivityManager.registerNetworkCallback(request, callback)

		awaitClose {
			runCatching { connectivityManager.unregisterNetworkCallback(callback) }
		}
	}
}

package com.uniquindio.thecatapp.data.local

import com.uniquindio.thecatapp.domain.model.Cat
import com.uniquindio.thecatapp.domain.model.CatBreed
import com.uniquindio.thecatapp.domain.model.CatCategory
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class CatMemoryStore @Inject constructor() {

    private val cats = listOf(
        Cat("1", "https://example.com/cat-1.jpg", breedId = "abys", categoryId = 1),
        Cat("2", "https://example.com/cat-2.jpg", breedId = "siam", categoryId = 2),
        Cat("3", "https://example.com/cat-3.jpg", breedId = "abys", categoryId = 2),
        Cat("4", "https://example.com/cat-4.jpg", breedId = "mau", categoryId = 1),
        Cat("5", "https://example.com/cat-5.jpg", breedId = "siam", categoryId = 3),
        Cat("6", "https://example.com/cat-6.jpg", breedId = "mau", categoryId = 3)
    )

    private val breeds = listOf(
        CatBreed("abys", "Abyssinian"),
        CatBreed("siam", "Siamese"),
        CatBreed("mau", "Egyptian Mau")
    )

    private val categories = listOf(
        CatCategory(1, "Funny"),
        CatCategory(2, "Sleepy"),
        CatCategory(3, "Cute")
    )

    fun getCats(page: Int, limit: Int, breedId: String?, categoryId: Int?): List<Cat> {
        val filtered = cats.filter { cat ->
            (breedId == null || cat.breedId == breedId) &&
                (categoryId == null || cat.categoryId == categoryId)
        }

        val fromIndex = page * limit
        return if (fromIndex >= filtered.size) {
            emptyList()
        } else {
            filtered.drop(fromIndex).take(limit)
        }
    }

    fun getBreeds(): List<CatBreed> = breeds

    fun getCategories(): List<CatCategory> = categories
}

package com.uniquindio.thecatapp.data.remote

import com.uniquindio.thecatapp.data.remote.dto.CatBreedDto
import com.uniquindio.thecatapp.data.remote.dto.CatCategoryDto
import com.uniquindio.thecatapp.data.remote.dto.CatImageDto

interface CatApiService {

    @GET("images/search")
    suspend fun searchImages(
        @Query("size") size: String = "med",
        @Query("mime_types") mimeTypes: String = "jpg,png",
        @Query("format") format: String = "json",
        @Query("order") order: String = "ASC",
        @Query("page") page: Int,
        @Query("limit") limit: Int = 20,
        @Query("breed_ids") breedIds: String? = null,
        @Query("category_ids") categoryIds: String? = null,
        @Query("include_breeds") includeBreeds: Int = 1,
        @Query("include_categories") includeCategories: Int = 1
    ): List<CatImageDto>

    @GET("images/{imageId}")
    suspend fun getImageById(
        @Path("imageId") imageId: String
    ): CatImageDto

    @GET("breeds")
    suspend fun getBreeds(): List<CatBreedDto>

    @GET("categories")
    suspend fun getCategories(): List<CatCategoryDto>
}

package com.uniquindio.thecatapp.data.repository

import com.uniquindio.thecatapp.data.local.CatMemoryStore
import com.uniquindio.thecatapp.features.list.BreedOption
import com.uniquindio.thecatapp.features.list.CatItem
import com.uniquindio.thecatapp.features.list.CategoryOption
import javax.inject.Inject

class CatRepositoryImpl @Inject constructor(
	private val memoryStore: CatMemoryStore
) : CatRepository {

	override suspend fun getCatImages(
		page: Int,
		limit: Int,
		breedId: String?,
		categoryId: Int?
	): Result<List<CatItem>> = runCatching {
		memoryStore.getCats(
			page = page,
			limit = limit,
			breedId = breedId,
			categoryId = categoryId
		)
	}

	override suspend fun getBreeds(): List<BreedOption> = memoryStore.getBreeds()

	override suspend fun getCategories(): List<CategoryOption> = memoryStore.getCategories()
}

